import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken(); int n = (int) in.nval;
        int[] x = new int[n];
        for (int k = 0; k < n; k++) { in.nextToken(); x[k] = (int) in.nval; }
        in.nextToken(); int m = (int) in.nval;
        int[] y = new int[m];
        for (int k = 0; k < m; k++) { in.nextToken(); y[k] = (int) in.nval; }
        StringBuilder sb = new StringBuilder();
        int i = 0, j = 0;
        while (i < n && j < m) {
            // take the smaller front value and move that pointer
            if (x[i] <= y[j]) sb.append(x[i++]).append(' ');
            else sb.append(y[j++]).append(' ');
        }
        while (i < n) sb.append(x[i++]).append(' ');   // leftover of x
        while (j < m) sb.append(y[j++]).append(' ');   // leftover of y
        System.out.println(sb.toString().trim());
    }
}

